import json
def transform(g):
    g=[r[:] for r in g]; h,w=len(g),len(g[0])
    # vertical lines: columns that are mostly 2 (outside keys)
    vcols=[c for c in range(w) if sum(1 for r in range(h) if g[r][c]==2)>=h//2]
    # find keys: 3x3 blocks centered on a 2 with 3 ring
    keys=[(r,c) for r in range(1,h-1) for c in range(1,w-1)
          if g[r][c]==2 and g[r-1][c]==g[r+1][c]==g[r][c-1]==g[r][c+1]==3
          and g[r-1][c-1]==g[r-1][c+1]==g[r+1][c-1]==g[r+1][c+1]==3]
    iskey=[[False]*w for _ in range(h)]
    for r,c in keys:
        for dr in(-1,0,1):
            for dc in(-1,0,1): iskey[r+dr][c+dc]=True
    hrows={r for r,c in keys}
    # also rows fully drawn as 2-roads
    hrows|={r for r in range(h) if sum(1 for v in g[r] if v==2)>=w//2}
    out=[r[:] for r in g]
    for r in hrows:
        road=sum(1 for v in g[r] if v==2)>=w//2
        for c in range(w):
            if iskey[r][c]: continue
            if c in vcols:
                out[r][c]=2  # crossing center
            elif not road:
                out[r][c]=1  # newly drawn horizontal line
            # if existing road, keep 2/0? demo1 kept 2s; zeros on a road? none seen
        for c in vcols:
            for dc in(-1,1):
                for dr in(-1,1):
                    rr,cc=r+dr,c+dc
                    if 0<=rr<h and 0<=cc<w and not iskey[rr][cc]:
                        out[rr][cc]=1
            for dr in(-1,1):
                rr=r+dr
                if 0<=rr<h and not iskey[rr][c]: out[rr][c]=1
    return out
